WITH session_totals AS (SELECT session_id, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(event_type))) AS event_type_values, ROUND((100 * SUM(CASE WHEN page = '/search' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_search FROM web_events GROUP BY session_id) SELECT s.browser, st.event_type_values, st.pct_search FROM sessions s INNER JOIN session_totals st ON s.id = st.session_id WHERE st.pct_search >= 22;
